CREATE VIEW v_d60_vwap3 AS SELECT sym, seq, SUM(price * vol) OVER (PARTITION BY sym ORDER BY seq ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) / SUM(vol) OVER (PARTITION BY sym ORDER BY seq ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS vwap3, MIN(price) OVER (PARTITION BY sym ORDER BY seq ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS pmin, MAX(price) OVER (PARTITION BY sym ORDER BY seq ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS pmax
FROM d60_ticks;
INSERT OR IGNORE INTO rolling_vwap_d60_meta VALUES ('module', 'rolling_vwap_d60');
